def build():
    items = []
    for i, (cat, sub, title, desc, tags, mins, typ) in enumerate(RAW, start=1):
        items.append({
            "id": f"R{i:03d}", "title": title, "description": desc, "category": cat, "subtopic": sub,
            "tags": tags, "duration_min": mins, "type": typ,
        })
    return items


if __name__ == "__main__":
    c = build()
    words = [len(x["description"].split()) for x in c]
    print(len(c), "resources;", "words min/mean/max:", min(words), round(sum(words) / len(words), 1), max(words))
    from collections import Counter
    print(Counter(x["category"] for x in c))
    print(len({x["subtopic"] for x in c}), "subtopics")
